    top_blob.create(outw, outh, num_output / out_elempack, out_elemsize, out_elempack, opt.blob_allocator);
    if (top_blob.empty())
        return -100;

    if (opt.use_sgemm_convolution)
    {
        const int size = outw * outh;
        const int maxk = kernel_w * kernel_h;

        Mat offset_unpacked;
        convert_packing(offset, offset_unpacked, 1, opt);

        Mat mask_unpacked;
        if (has_mask)
        {
            const Mat& mask = bottom_blobs[2];
            convert_packing(mask, mask_unpacked, 1, opt);
        }

        Mat bottom_im2col(size, maxk * channels, elemsize, elempack, opt.workspace_allocator);

#if __riscv_vector
        const int packn = csrr_vlenb() / 4;
        if (elempack == packn)
        {
            #pragma omp parallel for num_threads(opt.num_threads)
            for (int p = 0; p < channels; p++)
            {
                const Mat img = bottom_blob.channel(p);
                float* ptr = bottom_im2col.row(p * maxk);

                for (int u = 0; u < kernel_h; u++)
                {
                    for (int v = 0; v < kernel_w; v++)
                    {
                        const Mat offset_h_k = offset_unpacked.channel((u * kernel_w + v) * 2);
                        const Mat offset_w_k = offset_unpacked.channel((u * kernel_w + v) * 2 + 1);
                        const Mat mask_k = has_mask ? mask_unpacked.channel(u * kernel_w + v) : 0;

                        for (int i = 0; i < outh; i++)
                        {
                            for (int j = 0; j < outw; j++)
                            {
                                float offset_hv = offset_h_k.row(i)[j];
                                float offset_wv = offset_w_k.row(i)[j];

                                int h_in = i * stride_h - pad_top;
                                int w_in = j * stride_w - pad_left;

                                const float h_im = h_in + u * dilation_h + offset_hv;
                                const float w_im = w_in + v * dilation_w + offset_wv;

                                vfloat32m8_t _val = __riscv_vfmv_v_f_f32m8(0.f, __riscv_vsetvl_e32m8(packn));
                                bool cond = h_im > -1 && w_im > -1 && h_im < h && w_im < w;
                                if (cond)
                                {
                                    int h_low = (int)floorf(h_im);
                                    int w_low = (int)floorf(w_im);
                                    int h_high = h_low + 1;
                                    int w_high = w_low + 1;

                                    float lh = h_im - h_low;
                                    float lw = w_im - w_low;
                                    float hh = 1 - lh;
                                    float hw = 1 - lw;

                                    bool v1_cond = (h_low >= 0 && w_low >= 0);
                                    bool v2_cond = (h_low >= 0 && w_high <= w - 1);
                                    bool v3_cond = (h_high <= h - 1 && w_low >= 0);
                                    bool v4_cond = (h_high <= h - 1 && w_high <= w - 1);

                                    float w1 = hh * hw;
                                    float w2 = hh * lw;
                                    float w3 = lh * hw;
                                    float w4 = lh * lw;

                                    size_t vl = __riscv_vsetvl_e32m8(packn);
                                    vfloat32m8_t _v1 = v1_cond ? __riscv_vle32_v_f32m8(img.row(h_low) + w_low * packn, vl) : __riscv_vfmv_v_f_f32m8(0.f, vl);
                                    vfloat32m8_t _v2 = v2_cond ? __riscv_vle32_v_f32m8(img.row(h_low) + w_high * packn, vl) : __riscv_vfmv_v_f_f32m8(0.f, vl);
                                    vfloat32m8_t _v3 = v3_cond ? __riscv_vle32_v_f32m8(img.row(h_high) + w_low * packn, vl) : __riscv_vfmv_v_f_f32m8(0.f, vl);
                                    vfloat32m8_t _v4 = v4_cond ? __riscv_vle32_v_f32m8(img.row(h_high) + w_high * packn, vl) : __riscv_vfmv_v_f_f32m8(0.f, vl);

