if (opt.use_sgemm_convolution)
{
    const int size = outw * outh;
    const int maxk = kernel_w * kernel_h;

    Mat offset_unpacked;
    convert_packing(offset, offset_unpacked, 1, opt);

    Mat mask_unpacked;
    if (has_mask)
    {
        const Mat& mask = bottom_blobs[2];
        convert_packing(mask, mask_unpacked, 1, opt);
    }

    Mat bottom_blob_unpacked;
    convert_packing(bottom_blob, bottom_blob_unpacked, 1, opt);
    const int channels_p1 = bottom_blob_unpacked.c;

    Mat bottom_im2col(size, maxk * channels_p1, (size_t)4u, 1, opt.workspace_allocator);

    #pragma omp parallel for num_threads(opt.num_threads)
    for (int p = 0; p < channels_p1; p++)
    {
        const Mat img = bottom_blob_unpacked.channel(p);
        float* ptr = bottom_im2col.row(p * maxk);

        for (int u = 0; u < kernel_h; u++)
        {
            for (int v = 0; v < kernel_w; v++)
            {
                const Mat offset_h_k = offset_unpacked.channel((u * kernel_w + v) * 2);
                const Mat offset_w_k = offset_unpacked.channel((u * kernel_w + v) * 2 + 1);
                const Mat mask_k = has_mask ? mask_unpacked.channel(u * kernel_w + v) : Mat();

                for (int i = 0; i < outh; i++)
                {
                    for (int j = 0; j < outw; j++)
                    {
                        const float offset_hv = offset_h_k.row(i)[j];
                        const float offset_wv = offset_w_k.row(i)[j];

                        const int h_in = i * stride_h - pad_top;
                        const int w_in = j * stride_w - pad_left;

                        const float h_im = h_in + u * dilation_h + offset_hv;
                        const float w_im = w_in + v * dilation_w + offset_wv;

                        float val = 0.f;
                        const bool cond = h_im > -1 && w_im > -1 && h_im < h && w_im < w;
                        if (cond)
                        {
                            const int h_low = (int)floorf(h_im);
                            const int w_low = (int)floorf(w_im);
                            const int h_high = h_low + 1;
                            const int w_high = w_low + 1;

                            const float lh = h_im - h_low;
                            const float lw = w_im - w_low;
                            const float hh = 1 - lh;
                            const float hw = 1 - lw;

                            const bool v1_cond = (h_low >= 0 && w_low >= 0);
                            const bool v2_cond = (h_low >= 0 && w_high <= w - 1);
                            const bool v3_cond = (h_high <= h - 1 && w_low >= 0);
                            const bool v4_cond = (h_high <= h - 1 && w_high <= w - 1);

                            const float w1 = hh * hw;
                            const float w2 = hh * lw;
                            const float w3 = lh * hw;
                            const float w4 = lh * lw;

                            const float v1 = v1_cond ? img.row(h_low)[w_low] : 0.f;
                            const float v2 = v2_cond ? img.row(h_low)[w_high] : 0.f;
                            const float v3 = v3_cond ? img.row(h_high)[w_low] : 0.f;
                            const float v4 = v4_cond ? img.row(h_high)[w_high] : 0.f;
                            val = w1 * v1 + w2 * v2 + w3 * v3 + w4 * v4;

                            if (has_mask)
                                val *= mask_k.row(i)[j];
                        }

                        ptr[0] = val;
                        ptr += 1;
                    }
                }
            }
        }
    }

    Mat top2;
    top2.create(size, num_output, (size_t)4u, 1, opt.workspace_allocator);
    Option opt_b = opt;
    opt_b.blob_allocator = opt.workspace_allocator;
    int ret = gemm->forward(bottom_im2col, top2, opt_b);
    if (ret != 0) return ret;

    // reshape and pack
    Mat top_planar;
    top_planar.create(outw, outh, num_output, (size_t)4u, 1, opt.blob_allocator);
    for (int oc = 0; oc < num_output; oc++)
    {
        const float* src = top2.row(oc);
        float* dst = top_planar.channel(oc);
        // top2 is [size, num_output] with row-major access via row(oc)
        // Copy size elements
        memcpy(dst, src, size * sizeof(float));
    }
    if (activation)
    {
        activation->forward_inplace(top_planar, opt);
    }
    convert_packing(top_planar, top_blob, out_elempack, opt);
    return 0;
}

