                                const float lh = h_im - h_low;
                                const float lw = w_im - w_low;
                                const float hh = 1 - lh;
                                const float hw = 1 - lw;

                                const bool v1_cond = (h_low >= 0 && w_low >= 0);
                                const bool v2_cond = (h_low >= 0 && w_high <= w - 1);
                                const bool v3_cond = (h_high <= h - 1 && w_low >= 0);
                                const bool v4_cond = (h_high <= h - 1 && w_high <= w - 1);

                                const float w1 = hh * hw;
                                const float w2 = hh * lw;
                                const float w3 = lh * hw;
                                const float w4 = lh * lw;

                                const float v1 = v1_cond ? img.row(h_low)[w_low] : 0.f;
                                const float v2 = v2_cond ? img.row(h_low)[w_high] : 0.f;
                                const float v3 = v3_cond ? img.row(h_high)[w_low] : 0.f;
                                const float v4 = v4_cond ? img.row(h_high)[w_high] : 0.f;
                                val = w1 * v1 + w2 * v2 + w3 * v3 + w4 * v4;

                                if (has_mask)
                                    val *= mask_k.row(i)[j];
                            }

                            ptr[0] = val;
                            ptr += 1;
                        }
                    }
                }
            }
        }

        Mat top2;
        top2.create(size, num_output, (size_t)4u, 1, opt.workspace_allocator);
        Option opt_b = opt;
        opt_b.blob_allocator = opt.workspace_allocator;
        int ret = gemm->forward(bottom_im2col, top2, opt_b);
        if (ret != 0) return ret;

        // reshape and pack
        Mat top_planar;
        top_planar.create(outw, outh, num_output, (size_t)4u, 1, opt.blob_allocator);
        for (int oc = 0; oc < num_output; oc++)
        {
            const float* src = top2.row(oc);
            float* dst = top_planar.channel(oc);
            // top2 is [size, num_output] with row-major access via row(oc)
            // Copy size elements
            memcpy(dst, src, size * sizeof(float));
        }
        if (activation)
        {
            activation->forward_inplace(top_planar, opt);
        }
        convert_packing(top_planar, top_blob, out_elempack, opt);
        return 0;
    }

    // Fallback path for pack cases: unpack to elempack=1, run generic forward, then repack
    if (!(elempack == 1 && out_elempack == 1))
    {
        std::vector<Mat> bottoms_unpacked = bottom_blobs;
        Mat bottom_unpacked;
        convert_packing(bottom_blob, bottom_unpacked, 1, opt);
        bottoms_unpacked[0] = bottom_unpacked;

        Mat offset_unpacked;
        convert_packing(offset, offset_unpacked, 1, opt);
        bottoms_unpacked[1] = offset_unpacked;

        Mat mask_unpacked;
        if (has_mask)
        {
            const Mat& mask = bottom_blobs[2];
            convert_packing(mask, mask_unpacked, 1, opt);
            bottoms_unpacked[2] = mask_unpacked;
        }

        std::vector<Mat> tops_unpacked(1);
        tops_unpacked[0] = Mat();
        int ret = DeformableConv2D::forward(bottoms_unpacked, tops_unpacked, opt);
        if (ret != 0) return ret;

        // repack to out_elempack
        Mat top_packed;
        convert_packing(tops_unpacked[0], top_packed, out_elempack, opt);
        top_blob = top_packed;
        return 0;
    }

    // elempack == 1 && out_elempack == 1
    {
        const bool offset_not_pack = offset.elempack == 1;
        const bool mask_not_pack = has_mask ? bottom_blobs[2].elempack == 1 : true;
        const float* weight_ptr = elempack == 1 && out_elempack == 1 ? (const float*)weight_data_tm : (const float*)weight_data_plain;

        #pragma omp parallel for num_threads(opt.num_threads)
        for (int h_col = 0; h_col < outh; h_col++)
        {
            for (int w_col = 0; w_col < outw; w_col++)
            {
                int h_in = h_col * stride_h - pad_top;
                int w_in = w_col * stride_w - pad_left;
                for (int oc = 0; oc < num_output; oc++)
                {
                    float sum = 0.f;
                    if (bias_term)
                        sum = bias_data[oc];
                    for (int i = 0; i < kernel_h; i++)
                    {
                        for (int j = 0; j < kernel_w; j++)
                        {
                            float offset_hv = 0.f;
                            float offset_wv = 0.f;
                            float mask_ = 1.f;
                            if (offset_not_pack)
                            {
                                offset_hv = offset.channel((i * kernel_w + j) * 2).row(h_col)[w_col];
                                offset_wv = offset.channel((i * kernel_w + j) * 2 + 1).row(h_col)[w_col];
                            }
                            else
                            {
                                const int y_c = (i * kernel_w + j) * 2;
                                const int x_c = (i * kernel_w + j) * 2 + 1;
                                offset_hv = offset.channel(y_c / offset.elempack).row(h_col)[w_col * offset.elempack + y_c % offset.elempack];
                                offset_wv = offset.channel(x_c / offset.elempack).row(h_col)[w_col * offset.elempack + x_c % offset.elempack];
                            }
                            if (has_mask)
                            {
                                const Mat& mask = bottom_blobs[2];
                                if (mask_not_pack)
                                {
                                    mask_ = mask.channel(i * kernel_w + j).row(h_col)[w_col];
                                }
                                else
                                {
                                    const int m_c = i * kernel_w + j;
                                    mask_ = mask.channel(m_c / mask.elempack).row(h_col)[w_col * mask.elempack + m_c % mask.elempack];
                                }
                            }
                            const float h_im = h_in + i * dilation_h + offset_hv;
                            const float w_im = w_in + j * dilation_w + offset_wv;

                            const bool cond = h_im > -1 && w_im > -1 && h_im < h && w_im < w;
                            int h_low = 0;
                            int w_low = 0;
                            int h_high = 0;
                            int w_high = 0;
                            float w1 = 0.f;
                            float w2 = 0.f;
                            float w3 = 0.f;
                            float w4 = 0.f;
                            bool v1_cond = false;
                            bool v2_cond = false;
                            bool v3_cond = false;
                            bool v4_cond = false;
                            if (cond)
                            {
                                h_low = (int)floorf(h_im);
                                w_low = (int)floorf(w_im);
                                h_high = h_low + 1;
                                w_high = w_low + 1;

                                float lh = h_im - h_low;
                                float lw = w_im - w_low;
                                float hh = 1 - lh;
                                float hw = 1 - lw;

                                v1_cond = (h_low >= 0 && w_low >= 0);
                                v2_cond = (h_low >= 0 && w_high <= w - 1);
                                v3_cond = (h_high <= h - 1 && w_low >= 0);
                                v4_cond = (h_high <= h - 1 && w_high <= w - 1);

                                w1 = hh * hw;
                                w2 = hh * lw;
                                w3 = lh * hw;
                                w4 = lh * lw;
                            }

                            for (int ic = 0; ic < channels; ic++)
                            {
                                float val = 0.f;
                                if (cond)
                                {
                                    float v1 = v1_cond ? bottom_blob.channel(ic).row(h_low)[w_low] : 0.f;
                                    float v2 = v2_cond ? bottom_blob.channel(ic).row(h_low)[w_high] : 0.f;
                                    float v3 = v3_cond ? bottom_blob.channel(ic).row(h_high)[w_low] : 0.f;
                                    float v4 = v4_cond ? bottom_blob.channel(ic).row(h_high)[w_high] : 0.f;
                                    val = w1 * v1 + w2 * v2 + w3 * v3 + w4 * v4;
                                }
                                sum += val * mask_ * weight_ptr[((oc * channels + ic) * kernel_h + i) * kernel_w + j];
                            }
                        }
                    }
                    top_blob.channel(oc).row(h_col)[w_col] = activation_ss(sum, activation_type, activation_params);
                }
            }
        }
    }

    return 0;
}

