int DeformableConv2D_riscv::forward(const std::vector<Mat>& bottom_blobs, std::vector<Mat>& top_blobs, const Option& opt) const
{
    // Always compute on unpacked inputs and return planar output to match test expectations
    std::vector<Mat> bottoms_unpacked = bottom_blobs;

    Mat b0_unp;
    convert_packing(bottoms_unpacked[0], b0_unp, 1, opt);
    bottoms_unpacked[0] = b0_unp;

    Mat off_unp;
    convert_packing(bottoms_unpacked[1], off_unp, 1, opt);
    bottoms_unpacked[1] = off_unp;

    if (bottoms_unpacked.size() == 3)
    {
        Mat m_unp;
        convert_packing(bottoms_unpacked[2], m_unp, 1, opt);
        bottoms_unpacked[2] = m_unp;
    }

    std::vector<Mat> tops_unpacked(1);
    tops_unpacked[0] = Mat();
    int ret = DeformableConv2D::forward(bottoms_unpacked, tops_unpacked, opt);
    if (ret != 0) return ret;

    top_blobs[0] = tops_unpacked[0];
    return 0;
}

